// Mark the outreach sent and record an outbound interaction in one query.
function q(s){ return String(s==null?'':s).replace(/'/g, "''"); }
const o = $('Get Next Approved').item.json;
const query = `UPDATE app.outreach SET status = 'sent', sent_at = now() WHERE id = '${o.outreach_id}'; INSERT INTO app.interactions (recruiter_id, application_id, outreach_id, direction, channel, subject, body, message_id) VALUES ('${o.recruiter_id}', ${o.application_id ? `'${o.application_id}'` : 'NULL'}, '${o.outreach_id}', 'outbound', 'email', '${q(o.subject)}', '${q(o.body)}', 'sent-${o.outreach_id}'); INSERT INTO app.followups (recruiter_id, application_id, due_at, kind) VALUES ('${o.recruiter_id}', ${o.application_id ? `'${o.application_id}'` : 'NULL'}, now() + (interval '1 day' * ${Number($env.FOLLOWUP_DEFAULT_DAYS || 4)}), 'nudge');`;
return [{ json: { query } }];
